/* ── components/order-confirmation/order-confirmation.css ── */
/* -- Order Confirmation (website · Shop) ----------------------------------
   Confirms a completed purchase and provides its reference - a check that draws itself, the order number, what happens next and where to go. */

@layer components {
  /* every box in the block measures border-box - the same on any page */
  :where(.mk-order-confirmation, .mk-order-confirmation *, .mk-order-confirmation ::before, .mk-order-confirmation ::after) { box-sizing: border-box; }

  .mk-order-confirmation { display: grid; justify-items: center; gap: 1.5rem; max-width: 40rem; margin-inline: auto; padding: 2.5rem 1.5rem; text-align: center; }
  .mk-order-confirmation-check {
    width: 4.5rem;
    height: 4.5rem;
    color: #16a34a;

    & circle { fill: color-mix(in oklch, #16a34a 12%, transparent); stroke: currentColor; stroke-width: 2; }
    & path { fill: none; stroke: currentColor; stroke-width: 3; stroke-linecap: round; stroke-linejoin: round; stroke-dasharray: 30; stroke-dashoffset: 0; animation: mk-order-check 600ms 200ms cubic-bezier(.65,0,.35,1) both; }
  }
  @keyframes mk-order-check { from { stroke-dashoffset: 30; } }
  .mk-order-confirmation-title { margin: 0; font-size: clamp(1.5rem, 4vw, 2.25rem); font-weight: 700; letter-spacing: -0.025em; text-wrap: balance; }
  .mk-order-confirmation-lead { margin: -0.5rem 0 0; color: var(--muted-foreground); text-wrap: pretty;
    & code { padding: 0.125rem 0.375rem; border-radius: var(--radius-sm); background: var(--muted); color: var(--foreground); font-family: var(--font-mono); font-weight: 700; user-select: all; }
  }
  .mk-order-confirmation-details {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 14rem), 1fr));
    gap: 1px;
    width: 100%;
    margin: 0;
    overflow: hidden;
    border: 1px solid var(--border);
    border-radius: var(--radius-xl);
    background: var(--border);
    text-align: start;

    & div { display: grid; gap: 0.25rem; padding: 1rem 1.25rem; background: var(--card); }
    & dt { color: var(--muted-foreground); font-size: 0.75rem; font-weight: 600; letter-spacing: 0.06em; text-transform: uppercase; }
    & dd { margin: 0; font-size: 0.9375rem; }
    & address { font-style: normal; }
  }
  .mk-order-confirmation-steps { display: grid; gap: 0.75rem; width: 100%; margin: 0; padding: 0; list-style: none; counter-reset: mk-oc; text-align: start;
    & li { counter-increment: mk-oc; display: grid; grid-template-columns: 1.75rem minmax(0, 1fr); gap: 0.75rem; align-items: start; font-size: 0.9375rem; }
    & li::before { content: counter(mk-oc); display: grid; place-items: center; width: 1.75rem; height: 1.75rem; border-radius: 50%; background: var(--muted); font-size: 0.8125rem; font-weight: 700; }
    & span { color: var(--muted-foreground); }
  }
  .mk-order-confirmation-actions { display: flex; flex-wrap: wrap; justify-content: center; gap: 0.75rem; }

  /* -- Accessibility ------------------------------------------- */
  @media (prefers-reduced-motion: reduce) {
    .mk-order-confirmation-check path { animation: none; }
  }

  @media (forced-colors: active) {
    .mk-order-confirmation-check { color: CanvasText; }
    .mk-order-confirmation-details { border-color: CanvasText; }
  }
}

/* ── components/order-summary/order-summary.css ── */
/* -- Order Summary (website · Shop) ---------------------------------------
   Displays an order's items and charge breakdown - pictures with quantity badges, the lines, discount, shipping and total; collapsible on small screens. */

@layer components {
  /* every box in the block measures border-box - the same on any page */
  :where(.mk-order-summary, .mk-order-summary *, .mk-order-summary ::before, .mk-order-summary ::after) { box-sizing: border-box; }

  .mk-order-summary { display: grid; gap: 1.25rem; padding: 1.5rem; border-radius: var(--radius-xl); background: var(--muted); max-width: 26rem; }
  .mk-order-summary-title { margin: 0; font-size: 1rem; font-weight: 600; }
  .mk-order-summary-items { display: grid; gap: 1rem; margin: 0; padding: 0; list-style: none;
    & li { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 0.875rem; }
  }
  .mk-order-summary-thumb { position: relative;
    & img { display: block; width: 3.5rem; aspect-ratio: 4 / 5; object-fit: cover; border: 1px solid var(--border); border-radius: var(--radius-md); background: var(--background); }
    & b { position: absolute; top: -0.5rem; right: -0.5rem; display: grid; place-items: center; min-width: 1.25rem; height: 1.25rem; padding-inline: 0.25rem; border-radius: 999px; background: var(--muted-foreground); color: var(--background); font-size: 0.6875rem; font-weight: 700; box-sizing: border-box; }
  }
  .mk-order-summary-name { display: grid; font-size: 0.875rem; font-weight: 600;
    & small { color: var(--muted-foreground); font-size: 0.8125rem; font-weight: 400; }
  }
  .mk-order-summary-price { font-size: 0.875rem; font-weight: 600; font-variant-numeric: tabular-nums; }
  .mk-order-summary-totals { display: grid; gap: 0.5rem; margin: 0; padding-block-start: 1rem; border-block-start: 1px solid var(--border);
    & div { display: flex; justify-content: space-between; gap: 1rem; font-size: 0.875rem; }
    & dt { color: var(--muted-foreground); }
    & dd { margin: 0; font-variant-numeric: tabular-nums; }
    & [data-discount] dd { color: #15803d; }
    & [data-total] { align-items: baseline; margin-block-start: 0.5rem; padding-block-start: 0.875rem; border-block-start: 1px solid var(--border); }
    & [data-total] dt { color: var(--foreground); font-size: 1rem; font-weight: 600; }
    & [data-total] small { display: block; color: var(--muted-foreground); font-size: 0.75rem; font-weight: 400; }
    & [data-total] dd { font-size: 1.375rem; font-weight: 700; }
  }

  .mk-order-summary[data-variant="collapsible"] {
    gap: 0;
    padding: 0;

    & > summary { display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: 1rem 1.25rem; cursor: pointer; list-style: none; color: var(--primary); font-size: 0.9375rem; font-weight: 600; }
    & > summary::-webkit-details-marker { display: none; }
    & > summary span { display: inline-flex; align-items: center; gap: 0.375rem; }
    & > summary svg { width: 1rem; height: 1rem; transition: rotate 200ms ease; }
    &[open] > summary svg { rotate: 180deg; }
    & > summary b { color: var(--foreground); font-size: 1.125rem; font-variant-numeric: tabular-nums; }
    & > summary:focus-visible { outline: 2px solid var(--ring); outline-offset: -2px; border-radius: var(--radius-xl); }
    & > div { display: grid; gap: 1.25rem; padding: 0 1.25rem 1.25rem; }
  }

  /* -- Accessibility ------------------------------------------- */
  @media (prefers-reduced-motion: reduce) {
    .mk-order-summary[data-variant="collapsible"] > summary svg { transition: none; }
  }

  @media (forced-colors: active) {
    .mk-order-summary { border: 1px solid CanvasText; }
  }
}

/* ── components/otp-input/otp-input.css ── */
/* -- OTP Input -------------------------------------------------- */
/* One real <input> under a row of slots. The input keeps every native */
/* behaviour (paste, one-time-code autofill, selection, form value);   */
/* the slots are a mirror of its value.                                */

@layer components {
  .otp-input {
    --otp-input-slot-size: 2.75rem;

    position: relative;
    display: inline-flex;
    width: max-content;

    /* The field covers the slots so clicks, drags and taps land on the real
       control. Its own text is invisible — the slots do the drawing — but it
       stays a normal input to the browser and to assistive technology. */
    & > input {
      position: absolute;
      inset: 0;
      width: 100%;
      height: 100%;
      margin: 0;
      padding: 0;
      border: 0;
      background: transparent;
      color: transparent;
      caret-color: transparent;
      font-size: 1rem; /* >=16px keeps iOS from zooming on focus */
      text-align: center;
      outline: none;
      cursor: text;

      /* the selection highlight would show through the transparent text */
      &::selection {
        background: transparent;
      }

      &:disabled {
        cursor: not-allowed;
      }
    }
  }

  .otp-input-slots {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    pointer-events: none; /* the field beneath owns every pointer event */
  }

  .otp-input-slot {
    /* --otp-input-slot-size is the outer size, border included */
    box-sizing: border-box;
    display: grid;
    place-items: center;
    width: var(--otp-input-slot-size);
    height: var(--otp-input-slot-size);
    border: 1px solid var(--input);
    border-radius: var(--radius-md);
    background: var(--background);
    color: var(--foreground);
    font-family: var(--font-mono);
    font-size: 1.125rem;
    font-variant-numeric: tabular-nums;
    transition: border-color 150ms, box-shadow 150ms;

    &[data-filled] {
      border-color: var(--ring);
    }

    /* the slot the caret sits in — the field's own caret is hidden */
    &[data-active],
    &[data-caret] {
      border-color: var(--ring);
      box-shadow: 0 0 0 3px color-mix(in oklch, var(--ring) 25%, transparent);
    }

    &[data-caret]::after {
      content: "";
      width: 1px;
      height: 1.125rem;
      background: var(--foreground);
      animation: otp-input-caret 1s steps(2, start) infinite;
    }
  }

  /* Gap between groups, e.g. 3-3 for a six digit code. */
  .otp-input-separator {
    width: 0.75rem;
    height: 1px;
    background: var(--border);
    flex-shrink: 0;
  }

  /* -- Invalid ------------------------------------------------ */
  .otp-input[data-invalid] .otp-input-slot {
    border-color: var(--destructive);

    &[data-active],
    &[data-caret] {
      box-shadow: 0 0 0 3px color-mix(in oklch, var(--destructive) 25%, transparent);
    }
  }

  /* -- Disabled ----------------------------------------------- */
  /* Deliberately not a blanket opacity fade: the digits must stay readable,
     so only the surface dims while the border and text keep their contrast. */
  .otp-input:has(> input:disabled) .otp-input-slot {
    background: var(--muted);
    color: var(--muted-foreground);
    border-color: var(--border);
  }

  @keyframes otp-input-caret {
    0% { opacity: 1; }
    100% { opacity: 0; }
  }
}

@media (prefers-reduced-motion: reduce) {
  @layer components {
    .otp-input,
    .otp-input *,
    .otp-input::before,
    .otp-input::after,
    .otp-input *::before,
    .otp-input *::after,
    .otp-input-slot,
    .otp-input-slot::before,
    .otp-input-slot::after {
      transition: none;
      animation: none;
    }
  }
}

@media (prefers-contrast: more) {
  @layer components {
    .otp-input-slot {
      border-width: 2px;
      border-color: var(--foreground);
    }

    .otp-input[data-invalid] .otp-input-slot {
      border-color: var(--destructive);
    }
  }
}

@media (forced-colors: active) {
  @layer components {
    .otp-input-slot {
      border-color: ButtonText;
      color: ButtonText;

      &[data-active],
      &[data-caret] {
        border-color: Highlight;
      }
    }

    .otp-input[data-invalid] .otp-input-slot {
      border-color: LinkText;
    }

    .otp-input:has(> input:disabled) .otp-input-slot {
      border-color: GrayText;
      color: GrayText;
    }
  }
}

/* ── components/page-not-found/page-not-found.css ── */
/* -- 404 Page (website · Account & States) --------------------------------
   Tells visitors the page does not exist and helps them on - a big 404, a search, the most useful links and the way home. */

@layer components {
  /* every box in the block measures border-box - the same on any page */
  :where(.mk-page-not-found, .mk-page-not-found *, .mk-page-not-found ::before, .mk-page-not-found ::after) { box-sizing: border-box; }

  .mk-page-not-found { container: mk-page-not-found / inline-size; position: relative; isolation: isolate; display: grid; justify-items: center; gap: 1.25rem; width: 100%; padding: 3rem 1.5rem; overflow: hidden; text-align: center; }
  .mk-page-not-found-code { margin: 0; font-size: clamp(5rem, 22cqi, 10rem); font-weight: 800; line-height: 0.9; letter-spacing: -0.06em; color: transparent; -webkit-text-stroke: 2px color-mix(in oklch, var(--foreground) 25%, transparent); font-variant-numeric: tabular-nums; }
  .mk-page-not-found-title { margin: 0; font-size: 1.875rem; font-weight: 700; letter-spacing: -0.02em; }
  .mk-page-not-found-text { margin: 0; max-width: 28rem; color: var(--muted-foreground); text-wrap: pretty; }
  .mk-page-not-found-search { display: flex; gap: 0.5rem; width: 100%; max-width: 24rem;
    & .input { flex: 1; min-width: 0; }
  }
  .mk-page-not-found-links { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 11rem), 1fr)); gap: 0.5rem; width: 100%; max-width: 36rem; margin: 0.5rem 0 0; padding: 0; list-style: none; text-align: start;
    & a { display: grid; gap: 0.125rem; padding: 0.875rem 1rem; border: 1px solid var(--border); border-radius: var(--radius-lg); color: inherit; text-decoration: none; transition: border-color 150ms ease; }
    & a:hover { border-color: color-mix(in oklch, var(--foreground) 30%, var(--border)); }
    & a:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; }
    & strong { display: flex; align-items: center; gap: 0.375rem; font-size: 0.9375rem; }
    & strong svg { width: 1rem; height: 1rem; }
    & span { color: var(--muted-foreground); font-size: 0.8125rem; }
  }

  .mk-page-not-found[data-variant="illustrated"] {
    padding-block: 6rem;

    & .mk-page-not-found-code { position: absolute; top: 50%; left: 50%; z-index: -1; translate: -50% -55%; font-size: clamp(9rem, 45cqi, 22rem); -webkit-text-stroke: 0; background: linear-gradient(180deg, color-mix(in oklab, var(--chart-1) 30%, transparent), transparent 85%); -webkit-background-clip: text; background-clip: text; }
  }
  .mk-page-not-found[data-variant="minimal"] { gap: 0.75rem; padding-block: 2rem;
    & .mk-page-not-found-code { font-size: 4rem; -webkit-text-stroke: 0; color: var(--muted-foreground); }
  }

  /* -- Accessibility ------------------------------------------- */
  @media (prefers-reduced-motion: reduce) {
    .mk-page-not-found-links a { transition: none; }
  }

  @media (forced-colors: active) {
    .mk-page-not-found-code { -webkit-text-stroke-color: CanvasText; background: none; color: GrayText; }
  }
}

/* ── components/pagination/pagination.css ── */
@layer components {
  .pagination { display: flex; justify-content: center; }
  .pagination-list { display: flex; align-items: center; gap: 0.25rem; list-style: none; margin: 0; padding: 0; }
  .pagination-link, .pagination-prev, .pagination-next {
    display: inline-flex; align-items: center; justify-content: center;
    min-width: 2.25rem; height: 2.25rem; padding-inline: 0.5rem;
    border: 1px solid transparent; border-radius: var(--radius-md);
    font-size: 0.875rem; color: var(--foreground); text-decoration: none;
    cursor: pointer; outline: none;
    transition: background-color 150ms ease, border-color 150ms ease; gap: 0.25rem;
    &:hover { background-color: var(--accent); }
    &:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; }
    & svg { width: 1rem; height: 1rem; flex-shrink: 0; }

    /* Disabled state for prev/next at boundaries */
    &[aria-disabled="true"], &.disabled {
      pointer-events: none;
      opacity: 0.5;
    }
  }
  .pagination-prev, .pagination-next { padding-inline: 0.75rem; gap: 0.375rem; }
  .pagination-active { border-color: var(--border); background-color: var(--background); font-weight: 500; }
  .pagination-ellipsis {
    display: inline-flex; align-items: center; justify-content: center;
    width: 2.25rem; height: 2.25rem; color: var(--muted-foreground);
    & span { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; }
  }

  /* -- Sizes ----------------------------------------------------
     Set data-size on the .pagination nav; every cell (page links, prev/next,
     ellipsis) scales. :where() keeps each rule at one class of specificity
     so the .pagination-prev padding-inline above still wins per-item.
     md == the unsized default. */
  .pagination:where([data-size="xs"]) {
    & :is(.pagination-link, .pagination-prev, .pagination-next) { min-width: 1.75rem; height: 1.75rem; font-size: 0.75rem; }
    & .pagination-ellipsis { width: 1.75rem; height: 1.75rem; }
  }
  .pagination:where([data-size="sm"]) {
    & :is(.pagination-link, .pagination-prev, .pagination-next) { min-width: 2rem; height: 2rem; font-size: 0.8125rem; }
    & .pagination-ellipsis { width: 2rem; height: 2rem; }
  }
  .pagination:where([data-size="md"]) {
    & :is(.pagination-link, .pagination-prev, .pagination-next) { min-width: 2.25rem; height: 2.25rem; font-size: 0.875rem; }
    & .pagination-ellipsis { width: 2.25rem; height: 2.25rem; }
  }
  .pagination:where([data-size="lg"]) {
    & :is(.pagination-link, .pagination-prev, .pagination-next) { min-width: 2.5rem; height: 2.5rem; font-size: 1rem; }
    & .pagination-ellipsis { width: 2.5rem; height: 2.5rem; }
  }
  .pagination:where([data-size="xl"]) {
    & :is(.pagination-link, .pagination-prev, .pagination-next) { min-width: 2.75rem; height: 2.75rem; font-size: 1.125rem; }
    & .pagination-ellipsis { width: 2.75rem; height: 2.75rem; }
  }

  /* -- Variants (data-variant on the .pagination nav) -----------
     outline: every cell a bordered button; joined: one segmented bar -
     shared borders collapse, only the outer corners round (logical radii,
     so RTL mirrors for free). The active page gets a filled surface so it
     still stands out among bordered cells. */
  .pagination:is([data-variant="outline"], [data-variant="joined"]) {
    & :is(.pagination-link, .pagination-prev, .pagination-next) {
      border-color: var(--border);
      background-color: var(--background);
      box-shadow: var(--shadow-xs);
      &:hover { background-color: var(--accent); color: var(--accent-foreground); }
    }
    & .pagination-active { background-color: var(--accent); color: var(--accent-foreground); }
  }
  .pagination[data-variant="joined"] {
    & .pagination-list { gap: 0; }
    & :is(.pagination-link, .pagination-prev, .pagination-next, .pagination-ellipsis) { border-radius: 0; }
    /* the ellipsis joins the chain instead of floating between two groups */
    & .pagination-ellipsis { border: 1px solid var(--border); background-color: var(--background); }
    & .pagination-list > li:first-child > * { border-start-start-radius: var(--radius-md); border-end-start-radius: var(--radius-md); }
    & .pagination-list > li:last-child > * { border-start-end-radius: var(--radius-md); border-end-end-radius: var(--radius-md); }
    & .pagination-list > li + li > * { margin-inline-start: -1px; }
    /* the hovered / focused / active cell's own border stays on top */
    & :is(.pagination-link, .pagination-prev, .pagination-next):is(:hover, :focus-visible),
    & .pagination-active { position: relative; z-index: 1; }
  }

  /* -- Layout: split - previous / next as two equal columns across the
     full width (daisyUI's two-column pager) --------------------------- */
  .pagination[data-layout="split"] {
    width: 100%;
    & .pagination-list { display: grid; grid-template-columns: 1fr 1fr; gap: 0.5rem; width: 100%; }
    & .pagination-list > li { display: flex; }
    & :is(.pagination-link, .pagination-prev, .pagination-next) { flex: 1; }
  }
  .pagination[data-layout="split"][data-variant="joined"] .pagination-list { gap: 0; }

  /* -- Accessibility ------------------------------------------ */

  @media (prefers-reduced-motion: reduce) {
    .pagination-link, .pagination-prev, .pagination-next { transition: none; }
  }

  @media (prefers-contrast: more) {
    .pagination-link, .pagination-prev, .pagination-next {
      border-color: var(--border);
      &:hover { border-color: var(--foreground); }
    }
    .pagination-active { border-width: 2px; }
  }

  @media (forced-colors: active) {
    .pagination-active {
      border-color: Highlight;
    }
    .pagination-link, .pagination-prev, .pagination-next {
      &:hover { forced-color-adjust: none; background: Highlight; color: HighlightText; }
      &[aria-disabled="true"], &.disabled { color: GrayText; }
    }
    .pagination[data-variant="joined"] :is(.pagination-link, .pagination-prev, .pagination-next, .pagination-ellipsis) {
      border-color: ButtonText;
    }
  }
  /* -- Density ----------------------------------------------------
     data-density on the .pagination nav scales only the inter-cell gap —
     the size ladder owns cell dimensions, so size and density stay
     independent axes. Ratio mirrors sizing.css (0.75 / 1 / 1.25). */
  .pagination:where([data-density="compact"]) { & .pagination-list { gap: 0.125rem; } }
  .pagination:where([data-density="comfortable"]) { & .pagination-list { gap: 0.25rem; } }
  .pagination:where([data-density="spacious"]) { & .pagination-list { gap: 0.5rem; } }

}

/* ── components/panel/panel.css ── */
/* -- Panel component ----------------------------------------------
   A title bar inside a card - icon, title and tools (minimize / maximize are
   Swaps) above a scrolling body. Minimized it is the title bar only; as the
   pane of a border-layout region it takes the region with it: north / south
   shrink to the bar, west / east turn the bar into a vertical tab (after the
   ExtJS 4 border layout). Maximized it fills its border layout, a
   [data-panel-host] or the viewport. Builds on .card (surface, border,
   radius) and .swap (the tool faces). */

@layer components {
  .panel {
    /* the card's padding scale, a notch tighter for tool-like bodies */
    --_base: 1rem;
    --_bar: 2.5rem;
    --_bar-bg: color-mix(in oklch, var(--muted) 60%, var(--card));

    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    min-width: 0;
    min-height: 0;

    /* -- Title bar -------------------------------------------------- */
    & > .panel-header {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      flex: none;
      min-block-size: var(--_bar);
      box-sizing: border-box;
      padding-block: 0.25rem;
      padding-inline: 0.75rem 0.375rem;
      border-block-end: 1px solid var(--border);
      background: var(--_bar-bg);
      color: var(--foreground);
      user-select: none;
    }

    & .panel-icon {
      flex: none;
      width: 1rem;
      height: 1rem;
      color: var(--muted-foreground);
    }

    & .panel-title {
      flex: 1;
      min-inline-size: 0;
      margin: 0;
      overflow: hidden;
      font: inherit;
      font-size: 0.875rem;
      font-weight: 600;
      line-height: 1.25;
      white-space: nowrap;
      text-overflow: ellipsis;
    }

    /* tools: the swaps (and any .btn) at the end of the bar */
    & .panel-tools {
      display: flex;
      align-items: center;
      gap: 0.125rem;
      flex: none;
      margin-inline-start: auto;
    }

    /* small tool buttons - the swap at icon-button size */
    & > .panel-header .panel-tools .swap {
      min-width: 1.75rem;
      min-height: 1.75rem;
      color: var(--muted-foreground);

      & svg:not([class*="size-"]) { width: 1rem; height: 1rem; }
      &:hover:not(:has(> input:disabled)) { color: var(--accent-foreground); }
    }

    /* -- Body ----------------------------------------------------------- */
    & > .panel-body {
      flex: 1;
      min-block-size: 0;
      overflow: auto;
      padding: var(--_pad, 1rem);
    }
    /* a body that brings its own layout (a list, a table, a code view) */
    & > .panel-body[data-flush] { padding: 0; }

    & > .panel-footer {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      flex: none;
      padding: 0.5rem 0.75rem;
      border-block-start: 1px solid var(--border);
      background: var(--_bar-bg);
      font-size: 0.8125rem;
      color: var(--muted-foreground);
    }

    /* -- Minimized: the title bar only ------------------------------------- */
    &[data-minimized] {
      & > :not(.panel-header) { display: none; }
      & > .panel-header { border-block-end-color: transparent; }
    }
    /* the authored height (inline, or the resizer's px) gives way to the bar */
    &[data-minimized]:not([data-region="west"], [data-region="east"]) {
      height: auto !important;
      min-height: 0;
    }

    /* west / east: the bar turns into a vertical tab, the width to the bar's */
    &[data-minimized]:is([data-region="west"], [data-region="east"]) {
      width: auto !important;
      min-width: 0;
      /* the card's inline-size containment would size the tab to zero */
      container-type: normal;

      & > .panel-header {
        flex: 1;
        writing-mode: vertical-rl;
        padding-block: 0.25rem;
        padding-inline: 0.375rem 0.75rem;
        border-block-end: 0;
      }
      /* the restore tool leads, like ExtJS's collapsed placeholder */
      & .panel-tools { order: -1; margin-inline: 0 0.25rem; }
      & .panel-maximize { display: none; }
    }

    /* the minimize chevron points where the panel folds to */
    &[data-region="south"] .panel-minimize { rotate: 180deg; }
    &[data-region="west"] .panel-minimize { rotate: -90deg; }
    &[data-region="east"] .panel-minimize { rotate: 90deg; }

    /* -- Maximized: fills the viewport ... -------------------------------- */
    &[data-maximized] {
      position: fixed;
      inset: 0;
      z-index: 50;
      width: auto !important;
      height: auto !important;
      max-width: none;
      max-height: none;
      margin: 0;
      border-radius: 0;
      box-shadow: var(--shadow-xl);
    }
  }

  /* ... or its border layout / [data-panel-host] */
  :is(.border-layout, [data-panel-host])[data-panel-maximized] {
    position: relative;

    & .panel[data-maximized] {
      position: absolute;
      z-index: 20;
      border-radius: inherit;
    }
  }
  /* the regions step back so the layout is the containing block; their
     dividers rest under the maximized panel */
  .border-layout[data-panel-maximized] > .resizer {
    position: static;

    & > .resizer-handle { visibility: hidden; }
  }
  /* the region holding it rises too: a region may be a stacking context of
     its own (a <main> with a view-transition-name) that would trap the
     panel's z-index - grid items take z-index without being positioned, so
     the layout stays the containing block */
  .border-layout[data-panel-maximized] > :has(.panel[data-maximized]) { z-index: 20; }

  /* -- In a border layout: the region frames the panel ---------------------- */
  :where(.border-layout > .resizer, .border-layout > .border-layout-center, .border-layout) > .panel {
    border: 0;
    border-radius: 0;
  }
  /* the region shrinks with the panel: its pane is the panel */
  .border-layout > .resizer[data-panel-minimized] > .panel { overflow: hidden; }
  /* closed: the panel and its region leave the layout */
  .panel[hidden],
  .border-layout > [data-panel-closed] { display: none; }

  /* -- Accessibility -------------------------------------------- */
  @media (prefers-reduced-motion: reduce) {
    .panel .panel-minimize { transition: none; }
  }

  @media (prefers-contrast: more) {
    .panel > .panel-header { border-block-end-color: var(--foreground); }
    .panel .panel-title { font-weight: 700; }
  }

  @media (forced-colors: active) {
    .panel { border: 1px solid CanvasText; }
    .panel > .panel-header { border-block-end: 1px solid CanvasText; background: Canvas; color: CanvasText; }
    .panel .panel-icon { color: CanvasText; }
  }
}

/* ── components/paper/paper.css ── */
/* -- Paper -------------------------------------------------------------------
   A modern research-paper project page (the layout of the Nerfies / InternVL
   project pages) in the system's own tokens: a centered reading column for
   prose, figures and tables that may break out wider, a serif title, linked
   authors with affiliation marks, resource buttons, an abstract, numbered
   sections, captioned figures, findings, key numbers, BibTeX and a footer.
   CSS-only; the column is a named grid, so any child can opt into the wide
   track with .paper-wide. */

@layer components {
  :where(.paper, .paper *, .paper *::before, .paper *::after) {
    box-sizing: border-box;
  }

  .paper {
    --paper-measure: 46rem;
    --paper-wide: 64rem;
    --paper-gap: 2.5rem;

    display: grid;
    grid-template-columns:
      [full-start] minmax(1rem, 1fr)
      [wide-start] minmax(0, calc((var(--paper-wide) - var(--paper-measure)) / 2))
      [content-start] min(100% - 2rem, var(--paper-measure))
      [content-end] minmax(0, calc((var(--paper-wide) - var(--paper-measure)) / 2))
      [wide-end] minmax(1rem, 1fr)
      [full-end];
    row-gap: var(--paper-gap);
    padding-block: 3.5rem 0;
    background: var(--background);
    color: var(--foreground);
    font-family: var(--font-sans);
    font-size: 1rem;
    line-height: 1.7;
    container-type: inline-size;

    & > * {
      grid-column: content;
      min-inline-size: 0;
    }
    & > .paper-wide,
    & > .paper-hero,
    & > .paper-teaser {
      grid-column: wide;
    }
    & > .paper-footer {
      grid-column: full;
    }
    & :is(p, li) {
      text-wrap: pretty;
    }
    & a:not(.btn) {
      color: inherit;
      text-decoration: underline;
      text-decoration-color: color-mix(in oklab, currentColor 35%, transparent);
      text-underline-offset: 0.2em;
    }
    & a:not(.btn):hover {
      text-decoration-color: currentColor;
    }
  }

  /* -- the title block ------------------------------------------------------ */
  .paper-hero {
    display: grid;
    justify-items: center;
    gap: 1rem;
    text-align: center;
  }
  .paper-venue {
    display: inline-flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: center;
    gap: 0.5rem;
    margin: 0;
    color: var(--muted-foreground);
    font-family: var(--font-mono);
    font-size: 0.8125rem;
    letter-spacing: 0.04em;
  }
  .paper-title {
    max-inline-size: 22em;
    margin: 0;
    font-family: var(--font-serif);
    font-size: clamp(1.875rem, 4.6cqi, 3.25rem);
    font-weight: 500;
    line-height: 1.12;
    letter-spacing: -0.02em;
    text-wrap: balance;
  }
  .paper-title-sub {
    display: block;
    margin-block-start: 0.35em;
    color: var(--muted-foreground);
    font-size: 0.55em;
    font-weight: 400;
    letter-spacing: 0;
    line-height: 1.3;
  }
  .paper-authors,
  .paper-affiliations {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 0.25rem 1.25rem;
    margin: 0;
    padding: 0;
    list-style: none;
  }
  .paper-authors {
    font-size: 1.125rem;
    font-weight: 500;

    & sup {
      margin-inline-start: 0.1em;
      color: var(--muted-foreground);
      font-size: 0.65em;
    }
  }
  .paper-affiliations {
    color: var(--muted-foreground);
    font-size: 0.875rem;

    & sup {
      margin-inline-end: 0.15em;
      font-size: 0.75em;
    }
  }
  .paper-note {
    margin: 0;
    color: var(--muted-foreground);
    font-size: 0.8125rem;
  }
  .paper-links {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 0.5rem;
    margin-block-start: 0.5rem;

    & .btn {
      border-radius: 999px;
    }
  }

  /* -- a news line under the title ------------------------------------------ */
  .paper-news {
    display: flex;
    align-items: baseline;
    gap: 0.75rem;
    margin: 0;
    padding: 0.875rem 1.125rem;
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    background: color-mix(in oklab, var(--muted) 60%, var(--background));
    font-size: 0.9375rem;
    line-height: 1.55;

    & .badge {
      flex: none;
    }
  }

  /* -- figures ---------------------------------------------------------------- */
  .paper-teaser,
  .paper-figure {
    display: grid;
    gap: 0.75rem;
    margin: 0;

    & > :is(img, video, svg, .diagram) {
      inline-size: 100%;
      max-inline-size: 100%;
      border-radius: var(--radius-lg);
    }
    & > :is(img, video) {
      display: block;
      block-size: auto;
      border: 1px solid var(--border);
      background: var(--muted);
    }
  }
  .paper-teaser > figcaption,
  .paper-figure > figcaption,
  .paper-table-caption {
    color: var(--muted-foreground);
    font-size: 0.875rem;
    line-height: 1.55;
    text-align: center;
    text-wrap: balance;

    & b {
      color: var(--foreground);
      font-weight: 600;
    }
  }

  /* -- abstract and sections ------------------------------------------------- */
  .paper-abstract {
    display: grid;
    gap: 0.75rem;
    padding: 1.5rem 1.75rem;
    border-inline-start: 3px solid var(--primary);
    border-radius: 0 var(--radius-lg) var(--radius-lg) 0;
    background: color-mix(in oklab, var(--muted) 50%, var(--background));

    & > h2 {
      margin: 0;
      font-family: var(--font-serif);
      font-size: 1.375rem;
      font-weight: 500;
    }
    & > p {
      margin: 0;
      text-align: justify;
      hyphens: auto;
    }
  }
  .paper-section {
    display: grid;
    gap: 1rem;

    & > h2 {
      display: flex;
      align-items: baseline;
      gap: 0.75rem;
      margin: 0;
      padding-block-end: 0.5rem;
      border-block-end: 1px solid var(--border);
      font-family: var(--font-serif);
      font-size: 1.75rem;
      font-weight: 500;
      line-height: 1.25;
      letter-spacing: -0.01em;
      text-wrap: balance;
    }
    & > h3 {
      margin: 0.5rem 0 0;
      font-size: 1.0625rem;
      font-weight: 600;
    }
    & > p {
      margin: 0;
    }
    & > :is(ul, ol):not([class]) {
      margin: 0;
      padding-inline-start: 1.25rem;
    }
  }
  /* inside a section, .paper-wide breaks out of the reading column to the
     wide track (100cqi = the paper's width - it is the container) */
  .paper-section > .paper-wide {
    margin-inline: calc((100% - min(var(--paper-wide), 100cqi - 2rem)) / 2);
  }
  .paper-num {
    color: var(--muted-foreground);
    font-family: var(--font-mono);
    font-size: 0.75em;
    font-weight: 500;
  }

  /* -- findings: a row of numbered cards ------------------------------------- */
  .paper-findings {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(12rem, 1fr));
    gap: 1rem;
    margin: 0;
    padding: 0;
    list-style: none;
    counter-reset: paper-finding;

    /* a card of flowing text: inline code and links stay inline */
    & > li {
      display: block;
      padding: 1.125rem 1.25rem;
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      background: var(--card);
      color: var(--card-foreground);
      font-size: 0.9375rem;
      line-height: 1.55;
      counter-increment: paper-finding;
    }
    & > li::before {
      display: block;
      margin-block-end: 0.375rem;
      content: "Finding " counter(paper-finding);
      color: var(--muted-foreground);
      font-family: var(--font-mono);
      font-size: 0.75rem;
      letter-spacing: 0.06em;
      text-transform: uppercase;
    }
    & strong {
      font-weight: 600;
    }
    /* the leading phrase is the card's title */
    & > li > strong:first-child {
      display: block;
      margin-block-end: 0.25rem;
    }
    /* a tag leads its card on a line of its own */
    & > li > .paper-tag:first-child {
      display: table;
      margin-block-end: 0.5rem;
    }
  }

  /* -- table of contents: a numbered outline in columns --------------------- */
  .paper-toc {
    display: grid;
    gap: 0.75rem;
    padding: 1.125rem 1.25rem 1.25rem;
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    background: var(--card);
    color: var(--card-foreground);

    & > h2 {
      margin: 0;
      color: var(--muted-foreground);
      font: 600 0.75rem/1.2 var(--font-mono);
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }
    & ol {
      margin: 0;
      padding: 0;
      list-style: none;
    }
    & > ol {
      columns: 2 15rem;
      column-gap: 2rem;
    }
    & li {
      break-inside: avoid;
      padding-block: 0.125rem;
      font-size: 0.9375rem;
      line-height: 1.45;
    }
    & li li {
      padding-inline-start: 1.5rem;
      font-size: 0.875rem;
    }
    & a {
      display: flex;
      gap: 0.5rem;
      text-decoration: none;
    }
    & a:hover,
    & a:focus-visible {
      text-decoration: underline;
      text-underline-offset: 0.2em;
    }
    & .paper-num {
      flex: none;
      min-inline-size: 1.75rem;
      font-size: 0.8125rem;
    }
  }
  /* headings land below a sticky header when the ToC jumps to them */
  .paper :is(h2, h3)[id] {
    scroll-margin-block-start: 5rem;
  }

  /* -- epistemic tags (VAE-DIALECT): verified, hypothesis, unknown ---------- */
  /* solid chips in three chart colors at distinct steps; the text takes the
     contrasting end of the fill's own lightness, so every theme reads */
  .paper-tag {
    --paper-tag: var(--chart-2);

    display: inline-block;
    margin-inline-end: 0.375rem;
    padding: 0.0625rem 0.4375rem;
    border: 1px solid var(--paper-tag);
    border-radius: var(--radius-sm);
    background: var(--paper-tag);
    color: var(--background);
    font: 700 0.6875rem/1.5 var(--font-mono);
    letter-spacing: 0.04em;
    vertical-align: 0.1em;
    white-space: nowrap;

    &[data-tag="verified"] { --paper-tag: var(--chart-2); }
    &[data-tag="hypothesis"] { --paper-tag: var(--chart-1); }
    &[data-tag="unknown"] { --paper-tag: var(--chart-5); }
  }
  @supports (color: oklch(from red l c h)) {
    .paper-tag {
      /* light fill → near-black text, dark fill → white text */
      color: oklch(from var(--paper-tag) clamp(0.12, (0.64 - l) * 100, 0.99) 0 0);
    }
  }
  .paper-tags > li::before {
    content: none;
  }

  /* -- a code record, a quotation, a chart figure ---------------------------- */
  .paper-code {
    margin: 0;
    padding: 1rem 1.25rem;
    overflow-x: auto;
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    background: var(--muted);
    color: var(--foreground);
    font-family: var(--font-mono);
    font-size: 0.8125rem;
    line-height: 1.65;
  }
  .paper-quote {
    margin: 0;
    padding: 0.75rem 1.25rem;
    border-inline-start: 3px solid var(--border);
    color: var(--muted-foreground);
    font-family: var(--font-serif);
    font-size: 1.0625rem;
    font-style: italic;
    line-height: 1.6;

    & p {
      margin: 0;
    }
    /* a longer quotation: paragraphs, inline code, an attribution */
    & p + p {
      margin-block-start: 0.875rem;
    }
    & strong {
      color: var(--foreground);
      font-weight: 600;
    }
    & code {
      font-style: normal;
    }
    & > footer {
      margin-block-start: 1rem;
      color: var(--muted-foreground);
      font-family: var(--font-mono);
      font-size: 0.8125rem;
      font-style: normal;
      letter-spacing: 0.02em;
    }
  }
  .paper-chart {
    inline-size: 100%;
    block-size: 20rem;
  }

  /* -- key numbers: Statistic tiles ------------------------------------------ */
  .paper-numbers {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(10rem, 1fr));
    gap: 1rem;

    & > .statistic {
      padding: 1rem 1.125rem;
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      background: var(--card);
    }
    & .statistic-value {
      font-variant-numeric: tabular-nums;
    }
  }

  /* -- tables ----------------------------------------------------------------- */
  .paper-table {
    display: grid;
    gap: 0.75rem;
    margin: 0;
    overflow-x: auto;

    & table {
      inline-size: 100%;
      font-variant-numeric: tabular-nums;
    }
    /* booktabs: a heavy rule above and below, a light one under the head */
    & table {
      border-collapse: collapse;
      border-block: 1.5px solid var(--foreground);
    }
    & thead th {
      border-block-end: 1px solid var(--border);
      font-weight: 600;
    }
    & :is(td, th) {
      padding: 0.5rem 0.75rem;
      text-align: start;
    }
    & :is(td, th)[data-num] {
      text-align: end;
    }
    & tr[data-best] > td {
      font-weight: 600;
    }
  }

  /* -- BibTeX ------------------------------------------------------------------ */
  .paper-bibtex {
    display: grid;
    gap: 0.75rem;

    & > h2 {
      margin: 0;
      font-family: var(--font-serif);
      font-size: 1.375rem;
      font-weight: 500;
    }
    /* a plain <pre> - the BibTeX component brings its own frame */
    & > pre {
      margin: 0;
      padding: 1.125rem 1.25rem;
      overflow-x: auto;
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      background: var(--muted);
      color: var(--foreground);
      font-family: var(--font-mono);
      font-size: 0.8125rem;
      line-height: 1.6;
      tab-size: 2;
    }
  }

  /* -- footer ------------------------------------------------------------------ */
  .paper-footer {
    margin-block-start: 1.5rem;
    padding: 2rem 1rem 2.5rem;
    border-block-start: 1px solid var(--border);
    color: var(--muted-foreground);
    font-size: 0.8125rem;
    text-align: center;
    text-wrap: balance;

    & p {
      max-inline-size: var(--paper-measure);
      margin: 0 auto;
    }
    & p + p {
      margin-block-start: 0.5rem;
    }
  }

  /* -- narrow: the title block keeps its rhythm, prose loses the justify ------ */
  @container (max-width: 36rem) {
    .paper-abstract {
      padding: 1.125rem 1.25rem;

      & > p {
        text-align: start;
      }
    }
    .paper-section > h2 {
      font-size: 1.4rem;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .paper a:not(.btn) {
      transition: none;
    }
  }
  @media (prefers-contrast: more) {
    .paper-news,
    .paper-findings > li,
    .paper-numbers > .statistic,
    .paper-bibtex pre,
    .paper-section > h2 {
      border-color: var(--foreground);
    }
    .paper :is(.paper-venue, .paper-affiliations, .paper-note, .paper-title-sub, figcaption, .paper-footer) {
      color: var(--foreground);
    }
  }
  @media (forced-colors: active) {
    .paper-abstract {
      border-inline-start-color: CanvasText;
    }
    .paper-news,
    .paper-findings > li,
    .paper-numbers > .statistic,
    .paper-bibtex pre {
      border-color: CanvasText;
    }
  }
}

/* ── components/parallax/parallax.css ── */
/* -- Parallax --------------------------------------------------------
   Depth on scroll, no script. A .parallax scene is a view timeline (its
   passage through the scrollport); every .parallax-layer moves along it -
   far layers lag, near ones lead - so the picture separates into planes.
   A sticky scene (data-sticky + .parallax-stage) pins its stage while you
   scroll through it: the layers play over that whole distance (zoom, fade,
   spin). .parallax-drift moves in-flow elements at their own speed (columns
   of a photo wall), .parallax-reveal fades and lifts elements into view.
   Unsupported browsers and reduced motion get the still composition. */

@layer components {
  .parallax {
    position: relative;
    isolation: isolate;
    overflow: clip;
    view-timeline-name: --parallax;
    view-timeline-axis: block;
  }

  /* a layer fills the scene (or the stage) and moves by --parallax-speed:
     a percentage of its own height over the passage, or a length */
  .parallax-layer {
    --_speed: var(--parallax-speed, 0%);

    position: absolute;
    /* overscan by 1.5 x the absolute speed: the travel never shows an edge */
    inset: calc(-1.5 * max(var(--_speed), -1 * var(--_speed))) 0;
    display: grid;
    place-items: center;
    pointer-events: none;

    & > img,
    & > video,
    & > svg { width: 100%; height: 100%; object-fit: cover; }

    &[data-depth="far"] { --_speed: var(--parallax-speed, 50%); z-index: -4; }
    &[data-depth="mid"] { --_speed: var(--parallax-speed, 25%); z-index: -3; }
    &[data-depth="near"] { --_speed: var(--parallax-speed, -15%); z-index: -2; }
    &[data-depth="front"] { --_speed: var(--parallax-speed, -35%); z-index: 2; }
  }

  /* the content plane: in flow, interactive */
  .parallax-content { position: relative; z-index: 1; }

  /* sticky scene: tall (data-sticky sets the scroll distance, default 300%
     of the stage), the stage pins while the scene passes - the layers play
     over the pinned stretch (the timeline's contain range) */
  .parallax[data-sticky] {
    overflow: visible;
    height: calc(var(--parallax-stage, 100dvh) * var(--parallax-length, 3));
  }
  .parallax-stage {
    position: sticky;
    inset-block-start: 0;
    height: var(--parallax-stage, 100dvh);
    overflow: clip;
    isolation: isolate;
  }

  /* horizontal scenes (a sideways scroller) */
  .parallax[data-axis="inline"] { view-timeline-axis: inline; }

  /* in-flow elements at their own speed - a length (6rem) or a percentage */
  .parallax-drift { --_speed: var(--parallax-speed, 4rem); }

  @keyframes parallax-shift {
    from { translate: 0 calc(var(--_speed) * -1); }
    to { translate: 0 var(--_speed); }
  }
  @keyframes parallax-shift-inline {
    from { translate: calc(var(--_speed) * -1) 0; }
    to { translate: var(--_speed) 0; }
  }
  @keyframes parallax-zoom {
    from { scale: 1; }
    to { scale: var(--parallax-scale, 2.5); }
  }
  @keyframes parallax-fade {
    from { opacity: 1; }
    to { opacity: 0; }
  }
  @keyframes parallax-spin {
    to { rotate: var(--parallax-turn, 90deg); }
  }
  /* pass: in from small and transparent, hold, out large - words flying by */
  @keyframes parallax-pass {
    0% { opacity: 0; scale: 0.5; }
    35%, 65% { opacity: 1; scale: 1; }
    100% { opacity: 0; scale: 1.8; }
  }
  @keyframes parallax-reveal {
    from { opacity: 0; translate: 0 var(--parallax-rise, 3rem); scale: 0.98; }
  }
  @keyframes parallax-reveal-zoom {
    from { opacity: 0; scale: 0.85; }
  }
  @keyframes parallax-reveal-fade {
    from { opacity: 0; }
  }

  .parallax-layer,
  .parallax-drift { animation: parallax-shift linear both; }
  .parallax[data-axis="inline"] .parallax-layer { animation-name: parallax-shift-inline; }
  /* layer motions - stacked on the shift */
  .parallax-layer[data-motion="zoom"] { animation-name: parallax-shift, parallax-zoom; }
  .parallax-layer[data-motion="fade"] { animation-name: parallax-shift, parallax-fade; }
  .parallax-layer[data-motion="spin"] { animation-name: parallax-shift, parallax-spin; }
  .parallax-layer[data-motion="zoom fade"] { animation-name: parallax-shift, parallax-zoom, parallax-fade; }
  .parallax-layer[data-motion="pass"] { animation-name: parallax-shift, parallax-pass; }
  .parallax-reveal { animation: parallax-reveal ease-out both; }
  .parallax-reveal[data-reveal="zoom"] { animation-name: parallax-reveal-zoom; }
  .parallax-reveal[data-reveal="fade"] { animation-name: parallax-reveal-fade; }

  /* the timelines live in their own rules: a minifier must not fold them
     into the animation shorthand (reset-only there - dropped) */
  @supports (animation-timeline: view()) {
    .parallax-layer {
      animation-timeline: --parallax;
      animation-range: cover;
    }
    .parallax[data-sticky] .parallax-layer { animation-range: contain; }
    .parallax-drift {
      animation-timeline: view();
      animation-range: cover;
    }
    .parallax-reveal {
      animation-timeline: view();
      animation-range: entry 0% entry 80%;
    }
  }
  /* no scroll timelines: the still composition (no 0s jump to the end) */
  @supports not (animation-timeline: view()) {
    .parallax-layer,
    .parallax-drift,
    .parallax-reveal { animation: none; }
  }

  /* -- Accessibility ------------------------------------------- */
  @media (prefers-reduced-motion: reduce) {
    .parallax-layer,
    .parallax-drift,
    .parallax-reveal { animation: none; }
  }

  @media (forced-colors: active) {
    .parallax-layer { forced-color-adjust: none; }
  }
}

/* ── components/password-reset/password-reset.css ── */
/* -- Password Reset (website · Account & States) --------------------------
   Collects and confirms a replacement password - the new password with its rules, the confirmation, and the done state. */

@layer components {
  /* every box in the block measures border-box - the same on any page */
  :where(.mk-password-reset, .mk-password-reset *, .mk-password-reset ::before, .mk-password-reset ::after) { box-sizing: border-box; }

  .mk-password-reset {
    container: mk-password-reset / inline-size;
    display: grid;
    gap: 1.5rem;
    width: 100%;
    max-width: 24rem;
    margin-inline: auto;
    padding: 2rem;
    border: 1px solid var(--border);
    border-radius: var(--radius-xl);
    background: var(--card);
    color: var(--card-foreground);
    box-shadow: var(--shadow-sm);
  }
  .mk-password-reset-head { display: grid; justify-items: center; gap: 0.5rem; text-align: center;
    & > svg { width: 2rem; height: 2rem; color: var(--primary); }
    & h1, & h2 { margin: 0.25rem 0 0; font-size: 1.5rem; font-weight: 700; letter-spacing: -0.02em; }
    & p { margin: 0; color: var(--muted-foreground); font-size: 0.9375rem; text-wrap: pretty; }
  }
  .mk-password-reset form { display: grid; gap: 1rem; }
  .mk-password-reset .mk-auth-field { display: grid; gap: 0.375rem; }
  .mk-password-reset-row { display: flex; align-items: center; justify-content: space-between; gap: 1rem; font-size: 0.875rem;
    & a { color: var(--primary); font-weight: 500; text-decoration: none; }
    & a:hover { text-decoration: underline; text-underline-offset: 3px; }
  }
  .mk-password-reset-foot { margin: 0; color: var(--muted-foreground); font-size: 0.875rem; text-align: center;
    & a { color: var(--primary); font-weight: 600; text-decoration: none; }
    & a:hover { text-decoration: underline; text-underline-offset: 3px; }
  }
  .mk-password-reset .btn { width: 100%; }
  .mk-password-reset .input:user-valid { border-color: #16a34a; }
  .mk-password-reset-rules { margin: 0.25rem 0 0; padding-inline-start: 1.125rem; color: var(--muted-foreground); font-size: 0.8125rem; line-height: 1.6; }
  .mk-password-reset-icon { display: grid; place-items: center; width: 3rem; height: 3rem; border-radius: 50%; background: var(--muted);
    & svg { width: 1.375rem; height: 1.375rem; }
  }
  .mk-password-reset[data-variant="done"] .mk-password-reset-icon { background: color-mix(in oklch, #16a34a 14%, transparent); color: #15803d; }

  /* -- Accessibility ------------------------------------------- */
  @media (forced-colors: active) {
    .mk-password-reset { border-color: CanvasText; }
  }
}

/* ── components/payment-form/payment-form.css ── */
/* -- Payment Form (website · Shop) ----------------------------------------
   Collects or selects a payment method - card, PayPal or bank transfer as tabs, the card fields with the right keyboards and autofill, or a saved card. */

@layer components {
  /* every box in the block measures border-box - the same on any page */
  :where(.mk-payment-form, .mk-payment-form *, .mk-payment-form ::before, .mk-payment-form ::after) { box-sizing: border-box; }

  .mk-payment-form { display: grid; gap: 1rem; margin: 0; padding: 0; border: 0; min-width: 0; max-width: 32rem;
    & legend { margin-block-end: 1rem; padding: 0; font-size: 1.0625rem; font-weight: 600; }
  }
  .mk-payment-form-methods { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 0.5rem;
    & label { position: relative; display: grid; justify-items: center; gap: 0.25rem; padding: 0.75rem 0.5rem; border: 1px solid var(--border); border-radius: var(--radius-lg); font-size: 0.8125rem; font-weight: 600; cursor: pointer; }
    & input { position: absolute; inset: 0; margin: 0; opacity: 0; cursor: pointer; }
    & svg { width: 1.25rem; height: 1.25rem; }
    & label:has(:checked) { border-color: var(--primary); box-shadow: 0 0 0 1px var(--primary); background: color-mix(in oklch, var(--primary) 5%, transparent); }
    & label:has(:focus-visible) { outline: 2px solid var(--ring); outline-offset: 2px; }
  }
  .mk-payment-form-panel { display: none; gap: 1rem; padding: 1.25rem; border-radius: var(--radius-lg); background: var(--muted);
    & p { margin: 0; color: var(--muted-foreground); font-size: 0.875rem; }
    & dl { display: grid; gap: 0.5rem; margin: 0; font-size: 0.875rem; }
    & dl div { display: flex; justify-content: space-between; gap: 1rem; }
    & dt { color: var(--muted-foreground); }
    & dd { margin: 0; font-family: var(--font-mono); }
  }
  .mk-payment-form:has(input[value="card"]:checked) [data-method="card"],
  .mk-payment-form:has(input[value="paypal"]:checked) [data-method="paypal"],
  .mk-payment-form:has(input[value="bank"]:checked) [data-method="bank"] { display: grid; }
  .mk-payment-form-fields { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0.875rem; }
  .mk-payment-form-field { display: grid; gap: 0.375rem; &[data-span="full"] { grid-column: 1 / -1; } }
  .mk-payment-form-number { position: relative;
    & .input { padding-inline-end: 6.5rem; font-variant-numeric: tabular-nums; letter-spacing: 0.04em; }
    & ul { position: absolute; top: 50%; right: 0.5rem; translate: 0 -50%; display: flex; gap: 0.25rem; margin: 0; padding: 0; list-style: none; }
    & li { padding: 0.0625rem 0.3125rem; border: 1px solid var(--border); border-radius: 3px; background: var(--background); font-size: 0.5625rem; font-weight: 800; letter-spacing: 0.02em; }
  }
  .mk-payment-form-note { display: flex; align-items: center; gap: 0.375rem; color: var(--muted-foreground); font-size: 0.75rem;
    & svg { width: 0.875rem; height: 0.875rem; }
  }

  .mk-payment-form-saved { display: grid; gap: 0.5rem;
    & label { position: relative; display: grid; grid-template-columns: auto auto minmax(0, 1fr) auto; align-items: center; gap: 0.75rem; padding: 0.875rem 1rem; border: 1px solid var(--border); border-radius: var(--radius-lg); cursor: pointer; font-size: 0.9375rem; }
    & label:has(:checked) { border-color: var(--primary); box-shadow: 0 0 0 1px var(--primary); }
    & small { color: var(--muted-foreground); font-size: 0.8125rem; }
  }
  .mk-payment-form-brand { display: grid; place-items: center; width: 2.5rem; height: 1.625rem; border-radius: 4px; background: var(--foreground); color: var(--background); font-size: 0.5625rem; font-weight: 800; letter-spacing: 0.04em; }

  /* -- Accessibility ------------------------------------------- */
  @media (forced-colors: active) {
    .mk-payment-form-methods label:has(:checked), .mk-payment-form-saved label:has(:checked) { border-color: Highlight; }
  }
}

/* ── components/playlist-item/playlist-item.css ── */
/* -- Playlist Item (website · Media) --------------------------------------
   Represents one selectable track or episode within a playlist - number, cover, title, artist and length; the selected one shows "now playing" bars. */

@layer components {
  /* every box in the block measures border-box - the same on any page */
  :where(.mk-playlist-item, .mk-playlist-item *, .mk-playlist-item ::before, .mk-playlist-item ::after) { box-sizing: border-box; }

  .mk-playlist { display: grid; gap: 0.125rem; margin: 0; padding: 0; list-style: none; }
  .mk-playlist-item label {
    position: relative;
    display: grid;
    grid-template-columns: 1.75rem 2.75rem minmax(0, 1fr) auto;
    align-items: center;
    gap: 0.875rem;
    padding: 0.5rem 0.75rem;
    border-radius: var(--radius-lg);
    cursor: pointer;
    transition: background-color 150ms ease;

    &:hover { background: var(--accent); }
    & input { position: absolute; inset: 0; margin: 0; opacity: 0; cursor: pointer; }
  }
  .mk-playlist-item:has(input:checked) label { background: color-mix(in oklch, var(--primary) 9%, transparent); }
  .mk-playlist-item:has(input:focus-visible) label { outline: 2px solid var(--ring); outline-offset: -2px; }
  .mk-playlist-item-index { display: grid; place-items: center; color: var(--muted-foreground); font-size: 0.875rem; font-variant-numeric: tabular-nums; }
  .mk-playlist-item-bars { display: none; align-items: flex-end; gap: 2px; height: 0.875rem; font-style: normal;
    & b { width: 3px; height: 100%; border-radius: 1px; background: var(--primary); transform-origin: bottom; animation: mk-playlist-bars 900ms ease-in-out infinite alternate; }
    & b:nth-child(2) { animation-delay: -300ms; }
    & b:nth-child(3) { animation-delay: -600ms; }
  }
  @keyframes mk-playlist-bars { from { scale: 1 0.25; } to { scale: 1 1; } }
  .mk-playlist-item:has(input:checked) {
    & .mk-playlist-item-index > span { display: none; }
    & .mk-playlist-item-bars { display: flex; }
    & .mk-playlist-item-text strong { color: var(--primary); }
  }
  .mk-playlist-item-cover { display: block; width: 2.75rem; height: 2.75rem; object-fit: cover; border-radius: var(--radius-md); background: var(--muted); }
  .mk-playlist-item-text { display: grid; min-width: 0;
    & strong { overflow: hidden; font-size: 0.9375rem; font-weight: 600; text-overflow: ellipsis; white-space: nowrap; }
    & small { overflow: hidden; color: var(--muted-foreground); font-size: 0.8125rem; text-overflow: ellipsis; white-space: nowrap; }
  }
  .mk-playlist-item-desc { display: -webkit-box; margin-block-start: 0.25rem; overflow: hidden; color: var(--muted-foreground); font-size: 0.8125rem; line-height: 1.5; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
  .mk-playlist-item-duration { color: var(--muted-foreground); font-size: 0.8125rem; font-variant-numeric: tabular-nums; }

  .mk-playlist-item[data-variant="episode"] label { grid-template-columns: 1.75rem 4.5rem minmax(0, 1fr) auto; align-items: start; padding-block: 0.75rem;
    & .mk-playlist-item-cover { width: 4.5rem; height: 4.5rem; }
    & .mk-playlist-item-index, & .mk-playlist-item-duration { padding-block-start: 0.25rem; }
  }

  /* -- Accessibility ------------------------------------------- */
  @media (prefers-reduced-motion: reduce) {
    .mk-playlist-item label { transition: none; }
    .mk-playlist-item-bars b { animation: none; }
    .mk-playlist-item-bars b:nth-child(1) { scale: 1 0.6; }
    .mk-playlist-item-bars b:nth-child(3) { scale: 1 0.8; }
  }

  @media (forced-colors: active) {
    .mk-playlist-item:has(input:checked) label { outline: 2px solid Highlight; }
    .mk-playlist-item-bars b { background: Highlight; }
  }
}

/* ── components/popover/popover.css ── */
@layer components {
  .popover {
    position: fixed;
    inset: auto;
    margin: 0;
    border: 1px solid var(--border);
    border-radius: var(--radius-xl);
    background-color: var(--popover);
    color: var(--popover-foreground);
    padding: 1rem;

    /* -- Density --------------------------------------------------
       data-density on the .popover root scales the content padding
       (0.75 / 1 / 1.25 of the 1rem default); comfortable matches the
       unsized default. */
    &[data-density="compact"]     { padding: 0.75rem; }
    &[data-density="comfortable"] { padding: 1rem; }
    &[data-density="spacious"]    { padding: 1.25rem; }
    box-shadow: var(--shadow-md);
    width: 20rem;
    opacity: 0;
    translate: 0 -4px;
    transition: opacity 150ms ease, translate 150ms ease, display 150ms allow-discrete;

    /* -- Default: bottom center -- */
    position-area: bottom;
    margin-top: 4px;
    position-try-fallbacks: flip-block;

    &:popover-open {
      opacity: 1;
      translate: 0 0;
    }

    /* ----- Side variants ----- */
    &[data-side="top"] {
      position-area: top;
      margin-top: 0;
      margin-bottom: 4px;
      translate: 0 4px;
      &:popover-open { translate: 0 0; }
    }

    &[data-side="left"] {
      position-area: left;
      margin-top: 0;
      margin-right: 4px;
      translate: 4px 0;
      position-try-fallbacks: flip-inline;
      &:popover-open { translate: 0 0; }
    }

    &[data-side="right"] {
      position-area: right;
      margin-top: 0;
      margin-left: 4px;
      translate: -4px 0;
      position-try-fallbacks: flip-inline;
      &:popover-open { translate: 0 0; }
    }

    /* ----- Align variants (combined with side) ----- */
    &[data-align="start"] {
      &:not([data-side="left"]):not([data-side="right"]) { position-area: bottom left; }
      &[data-side="top"] { position-area: top left; }
      &[data-side="left"] { position-area: left top; }
      &[data-side="right"] { position-area: right top; }
    }

    &[data-align="end"] {
      &:not([data-side="left"]):not([data-side="right"]) { position-area: bottom right; }
      &[data-side="top"] { position-area: top right; }
      &[data-side="left"] { position-area: left bottom; }
      &[data-side="right"] { position-area: right bottom; }
    }
  }

  @starting-style {
    .popover:popover-open { opacity: 0; translate: 0 -4px; }
    .popover[data-side="top"]:popover-open { opacity: 0; translate: 0 4px; }
    .popover[data-side="left"]:popover-open { opacity: 0; translate: 4px 0; }
    .popover[data-side="right"]:popover-open { opacity: 0; translate: -4px 0; }
  }

  .popover-header { margin-bottom: 0.75rem; }
  .popover-title { margin: 0; font-size: 0.875rem; font-weight: 500; color: var(--foreground); }
  .popover-description { margin: 0.25rem 0 0; font-size: 0.8125rem; color: var(--muted-foreground); }
  .popover-content { font-size: 0.875rem; }

  @media (prefers-reduced-motion: reduce) {
    .popover {
      transition: none;
    }
  }
}

/* ── components/presentation/presentation.css ── */
/* -- Presentation component ------------------------------------
   Fixed-coordinate deck runtime: an artboard (default 1600×900) uniformly
   scaled to the mount, declarative entrance animations, native <progress>
   advance, presenter notes. Local --presentation-* custom properties are the
   deck's art-direction contract (literal defaults, token-free on purpose: a
   slide surface must stay identical under every theme); consumers override
   them per deck. */

@layer components {
  .presentation {
    /* artboard contract - override on the mount for other formats */
    --presentation-width: 1600;
    --presentation-height: 900;
    /* live uniform scale, owned by presentation.js (ResizeObserver) */
    --presentation-scale: 1;
    /* slide surfaces (fixed art direction, like the taxonomy badge colors) */
    --presentation-ink: #0d1424;
    --presentation-ink-foreground: #e9eef8;
    --presentation-paper: #ffffff;
    --presentation-paper-foreground: #101828;
    --presentation-accent: #38bdf8;
    /* motion: entrances come from the SHARED motion component (motion.css
       keyframes + [data-df-entrance]); a deck only tunes the --df-motion-*
       defaults for its artboard scale - per-element inline vars still win */
    --presentation-out: cubic-bezier(0.16, 1, 0.3, 1);
    --presentation-spring: cubic-bezier(0.34, 1.56, 0.64, 1);
    /* slow and deliberate: slide transitions (df$.anim, default 1500ms),
       entrances and the chart stage share one tempo */
    --presentation-duration: 1500ms;
    --df-motion-duration: var(--presentation-duration);
    --df-motion-ease: var(--presentation-out);
    --df-motion-distance: 3.5rem; /* artboard units - scales with the deck */

    position: relative;
    display: grid;
    width: 100%;
    aspect-ratio: var(--presentation-width) / var(--presentation-height);
    overflow: hidden;
    background: var(--presentation-ink);
    color: var(--presentation-ink-foreground);
    font-family: var(--font-sans);

    /* fullscreen MODE: when native fullscreen is active this element already
       owns the viewport; when the request was DENIED (embeds without
       allow="fullscreen") the same attribute pins it as a fixed overlay —
       one honest mode, two carriers. */
    &[data-fullscreen] {
      position: fixed;
      inset: 0;
      z-index: 50;
      width: 100vw;
      height: 100vh;
      aspect-ratio: auto;
    }

    & > [data-slide] {
      position: absolute;
      inset-block-start: 0;
      inset-inline-start: 0;
      inline-size: calc(var(--presentation-width) * 1px);
      block-size: calc(var(--presentation-height) * 1px);
      /* uniform artboard scale via zoom, NOT transform: the slide's
         transform belongs to the df$.anim transitions (slide/zoom/spin/flip
         keyframes animate transform - a scale() here would be overwritten
         mid-transition and the slide would jump to artboard size) */
      zoom: var(--presentation-scale);
      display: flex;
      flex-direction: column;
      justify-content: center;
      padding: calc(var(--presentation-height) * 0.08px) calc(var(--presentation-width) * 0.07px);
      box-sizing: border-box;
      /* the TRANSITION is the df$.anim engine (presentation.js plays a
         data-anim-out on the leaving slide and a data-anim-in on the
         arriving one); CSS only says who is on stage: the active slide on
         top, the leaving slide beneath it until its out-animation ends */
      visibility: hidden;

      &[data-active],
      &[data-leaving] {
        visibility: visible;
      }
      &[data-active] {
        z-index: 1;
      }
      &[data-leaving] {
        z-index: 0;
      }

      &[data-theme="ink"] {
        --presentation-surface: var(--presentation-ink);
        --presentation-on-surface: var(--presentation-ink-foreground);
      }
      &[data-theme="paper"] {
        --presentation-surface: var(--presentation-paper);
        --presentation-on-surface: var(--presentation-paper-foreground);
      }
      &[data-theme] {
        background: var(--presentation-surface);
        color: var(--presentation-on-surface);
        /* shipped components on a slide (table, badge, avatar, button, card)
           speak the SLIDE's surface, not the page theme: the existing
           semantic tokens are re-pointed at the deck's art direction, so a
           paper slide stays legible in dark mode and vice versa */
        --background: var(--presentation-surface);
        --foreground: var(--presentation-on-surface);
        --card: var(--presentation-surface);
        --card-foreground: var(--presentation-on-surface);
        --primary: var(--presentation-on-surface);
        --primary-foreground: var(--presentation-surface);
        --secondary: color-mix(in oklch, var(--presentation-on-surface) 10%, var(--presentation-surface));
        --secondary-foreground: var(--presentation-on-surface);
        --muted: color-mix(in oklch, var(--presentation-on-surface) 7%, var(--presentation-surface));
        --muted-foreground: color-mix(in oklch, var(--presentation-on-surface) 64%, var(--presentation-surface));
        --accent: color-mix(in oklch, var(--presentation-on-surface) 10%, var(--presentation-surface));
        --accent-foreground: var(--presentation-on-surface);
        --border: color-mix(in oklch, var(--presentation-on-surface) 18%, var(--presentation-surface));
        --input: color-mix(in oklch, var(--presentation-on-surface) 24%, var(--presentation-surface));
        --ring: var(--presentation-accent);
      }
    }

    /* charts on the artboard read at slide scale: the chart theme adapter
       derives every label, gap and stroke from --chart-font-size */
    & .chart {
      --chart-font-size: 24px;
    }

    /* -- the chart stage: ONE chart for the whole deck (chart.deck()) -------
       A deck-level layer in artboard coordinates (same scale transform as
       the slides) stacked ABOVE them, so every slide keeps its own surface.
       Slides that name a data-chart-state show it; the chart morphs from
       state to state while the slides crossfade underneath. Hidden = faded
       out in step with the slide fade, never unmounted. */
    & > .presentation-stage {
      position: absolute;
      inset-block-start: 0;
      inset-inline-start: 0;
      z-index: 2;
      inline-size: calc(var(--presentation-width) * 1px);
      block-size: calc(var(--presentation-height) * 1px);
      transform: scale(var(--presentation-scale));
      transform-origin: top left;
      visibility: hidden;
      opacity: 0;
      pointer-events: none;
      transition:
        opacity var(--presentation-duration) var(--presentation-out),
        visibility 0s linear var(--presentation-duration);

      &[data-visible] {
        visibility: visible;
        opacity: 1;
        pointer-events: auto;
        transition: opacity var(--presentation-duration) var(--presentation-out);
      }
    }
    /* a curtain (blocksIn → blocksOut) passes over the SLIDES; the chart
       stage steps aside while it runs and returns with the arriving slide */
    &[data-curtain] > .presentation-stage[data-visible] {
      opacity: 0;
      transition-duration: 300ms;
    }

    /* -- entrances: the SHARED motion component owns the vocabulary --------
       Slides simply carry [data-df-entrance] / [data-df-draw] / [data-df-
       stagger] elements; the keyframes + --df-motion-* tunables live in
       motion.css (shipped in the same all.css bundle). The deck runtime
       REPLAYS every entrance when its slide activates - revisiting a slide
       re-runs its entrance, and animations (unlike transitions) fire
       deterministically on first application, so decks animate correctly on
       load without a rendered "from" state. */

    /* -- in-slide chrome (artboard coordinates, scales with the deck) ------ */

    /* header line: a mono eyebrow strip with a hairline rule, pinned to the
       slide's top edge - section label left, optional meta right */
    & .presentation-header {
      position: absolute;
      inset-block-start: 0;
      inset-inline: 0;
      display: flex;
      align-items: baseline;
      gap: 1.25rem;
      padding: 3.5rem 4.5rem 1.75rem;
      font-family: var(--font-mono);
      font-size: 1.5rem;
      letter-spacing: 0.14em;
      text-transform: uppercase;
      color: color-mix(in oklch, currentColor 65%, transparent);
      border-block-end: 1px solid color-mix(in oklch, currentColor 16%, transparent);

      /* the accent tick gives the line a deliberate start, not a stray rule */
      &::before {
        content: '';
        inline-size: 2.75rem;
        block-size: 0.3rem;
        align-self: center;
        background: var(--presentation-accent);
      }

      /* the LAST span (meta) rides to the right edge - label stays with the tick */
      & > :last-child {
        margin-inline-start: auto;
      }
    }

    /* slide number: NN ⁄ NN in the bottom corner - the fraction slash (U+2044)
       is inherently slanted, so the motif needs no extra decoration. The
       runtime fills the text; authors just drop the element into a slide. */
    & .presentation-slide-number {
      position: absolute;
      inset-block-end: 2.75rem;
      /* bottom-LEFT: the bottom-right corner belongs to the deck controls */
      inset-inline-start: 4.5rem;
      font-family: var(--font-mono);
      font-size: 1.6rem;
      font-weight: 500;
      letter-spacing: 0.08em;
      color: color-mix(in oklch, currentColor 55%, transparent);
    }

    /* -- chrome (outside slide coordinates, viewport-fixed) -------------- */
    & .presentation-controls {
      position: absolute;
      inset-block-end: 1rem;
      inset-inline-end: 1rem;
      display: flex;
      align-items: center;
      gap: 0.375rem;
      z-index: 3;
    }

    & .presentation-control {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      inline-size: 2rem;
      block-size: 2rem;
      padding: 0;
      border: 1px solid color-mix(in oklch, var(--presentation-paper-foreground) 18%, transparent);
      border-radius: var(--radius-md);
      background: color-mix(in oklch, var(--presentation-paper) 82%, transparent);
      color: var(--presentation-paper-foreground);
      cursor: pointer;
      font: inherit;
      line-height: 1;

      &:hover {
        background: color-mix(in oklch, var(--presentation-paper) 95%, transparent);
      }
      &:disabled {
        opacity: 0.4;
        cursor: default;
      }
    }

    & .presentation-counter {
      font-family: var(--font-mono);
      font-size: 0.75rem;
      padding-inline: 0.5rem;
      color: var(--presentation-ink-foreground);
      background: color-mix(in oklch, var(--presentation-ink) 60%, transparent);
      border-radius: var(--radius-sm);
    }

    /* native <progress> - the platform's completion indicator */
    & .presentation-progress {
      position: absolute;
      inset-block-end: 0;
      inset-inline: 0;
      inline-size: 100%;
      block-size: 3px;
      margin: 0;
      border: none;
      background: color-mix(in oklch, var(--presentation-ink-foreground) 18%, transparent);
      accent-color: var(--presentation-accent);
      z-index: 3;

      &::-webkit-progress-bar { background: color-mix(in oklch, var(--presentation-ink-foreground) 18%, transparent); }
      &::-webkit-progress-value { background: var(--presentation-accent); }
      &::-moz-progress-bar { background: var(--presentation-accent); }
    }

    /* presenter notes - hidden until the deck toggles [data-notes] */
    & .presentation-note {
      display: none;
    }
    &[data-notes] > [data-slide][data-active] > .presentation-note {
      display: block;
      position: absolute;
      inset-block-end: 0;
      inset-inline: 0;
      margin: 0;
      padding: 1.25rem 4rem;
      font-size: 1.75rem;
      line-height: 1.4;
      background: color-mix(in oklch, #000000 82%, transparent);
      border-block-start: 1px solid color-mix(in oklch, #ffffff 20%, transparent);
      color: #ffffff;
    }

    /* slide typography helpers (fixed artboard sizes, not site type scale) */
    & .presentation-eyebrow {
      font-family: var(--font-mono);
      font-size: 1.5rem;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      opacity: 0.7;
      margin: 0 0 1rem;
    }
    & .presentation-title {
      font-size: 5.5rem;
      line-height: 1.05;
      letter-spacing: -0.02em;
      font-weight: 700;
      margin: 0 0 1.5rem;
      text-wrap: balance;
    }
    & .presentation-lede {
      font-size: 2rem;
      line-height: 1.4;
      opacity: 0.85;
      margin: 0;
      text-wrap: pretty;
    }
  }

  /* accessibility: honor motion + contrast preferences (REQUIRED). Entrances
     flatten via motion.css's own 1ms rule (keeps the JS finished contract);
     here only the deck's own slide-fade transition flattens. */
  @media (prefers-reduced-motion: reduce) {
    .presentation > [data-slide],
    .presentation > .presentation-stage {
      transition: none;
    }
  }

  @media (prefers-contrast: more) {
    .presentation .presentation-control {
      border-width: 2px;
      border-color: var(--presentation-paper-foreground);
    }
  }

  @media (forced-colors: active) {
    .presentation .presentation-control {
      border-color: CanvasText;
      color: CanvasText;
      background: Canvas;
    }
    .presentation .presentation-progress {
      border-block-start: 1px solid CanvasText;
    }
  }
}

/* ── components/press-item/press-item.css ── */
/* -- Press Item (website · Company) ---------------------------------------
   Links to one external media mention with publication metadata - the outlet, the date and the headline, a pull quote, or a compact list row. */

@layer components {
  /* every box in the block measures border-box - the same on any page */
  :where(.mk-press-item, .mk-press-item *, .mk-press-item ::before, .mk-press-item ::after) { box-sizing: border-box; }

  .mk-press-item {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    padding: 1.5rem;
    border: 1px solid var(--border);
    border-radius: var(--radius-xl);
    background: var(--card);
    color: var(--card-foreground);
    transition: border-color 150ms ease;

    &:hover { border-color: color-mix(in oklch, var(--foreground) 25%, var(--border)); }
  }
  .mk-press-item { position: relative; }
  .mk-press-item-title a::after { content: ""; position: absolute; inset: 0; border-radius: inherit; }
  .mk-press-item-title a:focus-visible { outline: none; }
  .mk-press-item:has(.mk-press-item-title a:focus-visible) { outline: 2px solid var(--ring); outline-offset: 2px; }
  /* zero specificity: any block rule may still position its controls */
  :where(.mk-press-item :is(button, input, select, label, .btn):not(.mk-press-item-title a)) { position: relative; z-index: 1; }
  .mk-press-item-meta { display: flex; align-items: baseline; justify-content: space-between; gap: 1rem; color: var(--muted-foreground); font-size: 0.8125rem; }
  .mk-press-item-publication { color: var(--foreground); font-size: 1.0625rem; font-weight: 800; letter-spacing: -0.02em; }
  .mk-press-item-title { margin: 0; font-size: 1.125rem; font-weight: 600; line-height: 1.35; text-wrap: balance;
    & a { color: inherit; text-decoration: none; }
  }
  .mk-press-item-quote { margin: 0; font-family: var(--font-serif); font-size: 1.25rem; line-height: 1.45; text-wrap: pretty;
    & p { margin: 0; }
    & p::before { content: "“"; }
    & p::after { content: "”"; }
  }
  .mk-press-item-more { display: inline-flex; align-items: center; gap: 0.25rem; margin-block-start: auto; color: var(--primary); font-size: 0.875rem; font-weight: 600;
    & svg { width: 0.875rem; height: 0.875rem; }
  }

  .mk-press-item[data-variant="quote"] {
    & .mk-press-item-title { order: 3; color: var(--muted-foreground); font-size: 0.875rem; font-weight: 500; }
    & .mk-press-item-more { order: 4; }
  }

  .mk-press-item[data-variant="compact"] {
    display: grid;
    grid-template-columns: 9rem minmax(0, 1fr) auto;
    align-items: baseline;
    gap: 1rem;
    padding: 1rem 0.5rem;
    border-width: 0 0 1px;
    border-radius: 0;
    background: transparent;

    & .mk-press-item-meta { display: contents; }
    & time { grid-column: 3; grid-row: 1; }
    & .mk-press-item-title { grid-column: 2; grid-row: 1; font-size: 1rem; }
    & .mk-press-item-more { display: none; }
  }

  /* -- Accessibility ------------------------------------------- */
  @media (prefers-reduced-motion: reduce) {
    .mk-press-item { transition: none; }
  }

  @media (forced-colors: active) {
    .mk-press-item { border-color: CanvasText; }
  }
}

/* ── components/pricing/pricing.css ── */
/* -- Pricing (marketing) -------------------------------------------
   Section head + billing toggle (composed from the tabs component) +
   plan cards. The featured plan upgrades its border - no layout shift. */

@layer components {
  .mk-pricing {
    container: mk-pricing / inline-size;
    display: flex;
    flex-direction: column;
    gap: 3rem;
    width: 100%;
    max-width: 80rem;
    margin-inline: auto;
    padding-inline: 1.25rem;
  }

  /* centered stack: eyebrow/title/desc + toggle all share the section's
     center line (align-items, not text-align - the toggle is a box) */
  .mk-pricing-head { display: flex; flex-direction: column; align-items: center; gap: 1.25rem; }

  .mk-pricing-eyebrow { color: var(--primary); font-size: 1rem; font-weight: 500; }

  .mk-pricing-title {
    line-height: 1.15;
    margin: 0;
    font-size: 1.875rem;
    font-weight: 500;
    letter-spacing: -0.025em;
    text-wrap: balance;
  }

  .mk-pricing-desc { margin: 0; max-width: 42rem; color: var(--muted-foreground); font-size: 1rem; text-wrap: pretty; }

  /* Segmented billing toggle: real radios + :has() - keyboard, screen
     readers, and form semantics work natively; one checked radio flips
     every plan's price pair, which per-tab aria-controls could not. */
  .mk-pricing-billing {
    display: inline-flex;
    align-self: center;
    gap: 0.25rem;
    padding: 0.25rem;
    border-radius: var(--radius-md);
    background: var(--muted);

    & label {
      display: inline-flex;
      align-items: center;
      gap: 0.375rem;
      padding: 0.375rem 0.75rem;
      border-radius: var(--radius-sm);
      font-size: 0.875rem;
      font-weight: 500;
      color: var(--muted-foreground);
      cursor: pointer;
    }

    & label:has(input:checked) {
      background: var(--background);
      color: var(--foreground);
      box-shadow: var(--shadow-2xs);
    }

    /* keyboard focus lands on the radio - show the ring on its label */
    & label:has(input:focus-visible) { outline: 2px solid var(--ring); outline-offset: 2px; }
  }

  /* price swap: each plan ships yearly + monthly rows; the checked radio
     anywhere in the section flips every plan at once via :has() */
  .mk-plan-price.mk-price-monthly { display: none; }

  .mk-pricing:has(.mk-bill-monthly:checked) {
    & .mk-plan-price.mk-price-yearly { display: none; }
    & .mk-plan-price.mk-price-monthly { display: flex; }
  }

  .mk-plans { display: grid; align-items: stretch; gap: 1.25rem; }

  .mk-plan {
    position: relative;
    display: flex;
    flex-direction: column;
    gap: 1.25rem;
    width: 100%;
    box-sizing: border-box;
    padding-block: 1.5rem;
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    background: var(--card);
    color: var(--card-foreground);
    box-shadow: var(--shadow-sm);

    /* featured plan: 2px primary border (same box size → no shift) and a
       soft primary wash from the top */
    &[data-featured] {
      border: 2px solid var(--primary);
      background:
        radial-gradient(120% 60% at 50% 0%, color-mix(in oklch, var(--primary) 9%, transparent), transparent 70%),
        var(--card);
      box-shadow: var(--shadow-lg);
    }

  }

  /* in an aura (shapes.css): the light is the border - the plan drops its own */
  .aura > .mk-plan {
    border-color: transparent;
    border-radius: var(--radius-lg);
  }
  .mk-plans > .aura { --shape-round: var(--radius-lg); }

  .mk-plan-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.5rem;
    padding-inline: 1.5rem;
  }

  .mk-plan-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 3rem;
    height: 3rem;
    flex-shrink: 0;
    border: 1px solid var(--border);
    border-radius: var(--radius-md);
    background: var(--muted);

    & svg { width: 1rem; height: 1rem; color: var(--primary); }
  }

  .mk-plan-body { display: flex; flex-direction: column; gap: 0.5rem; padding-inline: 1.5rem; }

  .mk-plan-title { font-size: 1.125rem; font-weight: 600; line-height: 1.3; margin: 0; }

  .mk-plan-desc { margin: 0; font-size: 0.875rem; line-height: 1.5; color: var(--muted-foreground); }

  .mk-plan-price {
    display: flex;
    gap: 0.5rem;
    margin-block-start: auto;
    padding-inline: 1.5rem;
  }

  .mk-plan-amount {
    align-self: flex-end;
    font-size: 3rem;
    font-weight: 500;
    line-height: 1;
    letter-spacing: -0.025em;
    font-variant-numeric: tabular-nums;
  }

  .mk-plan-unit { display: flex; flex-direction: column; align-self: flex-end; }
  .mk-plan-unit-label { font-size: 0.875rem; font-weight: 500; }
  .mk-plan-unit-note { font-size: 0.875rem; color: var(--muted-foreground); }

  .mk-plan-cta { padding-inline: 1.5rem; & .btn { width: 100%; } }

  .mk-plan-features {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 0.75rem;
    padding-inline: 1.5rem;
  }

  .mk-plan-features { margin: 0 1.5rem; padding: 1.25rem 0 0; border-block-start: 1px dashed var(--border); list-style: none; }

  /* the check sits in a small tinted disc */
  .mk-plan-feature {
    display: flex;
    align-items: flex-start;
    gap: 0.625rem;
    font-size: 0.9375rem;

    & svg {
      width: 1.125rem;
      height: 1.125rem;
      margin-block-start: 0.125rem;
      padding: 0.1875rem;
      border-radius: 50%;
      background: color-mix(in oklch, var(--primary) 12%, transparent);
      color: var(--primary);
      flex-shrink: 0;
      box-sizing: border-box;
    }
    & span { flex: 1; }
    &[data-muted] { color: var(--muted-foreground); }
    &[data-muted] svg { background: var(--muted); color: var(--muted-foreground); }
  }

  /* the featured plan's label: a filled Badge with a sparkle */
  .mk-plan-badge { gap: 0.25rem; }

  /* a saving next to the billing choice (a Badge) */
  .mk-pricing-billing .badge { margin-inline-start: 0.125rem; }

  @container mk-pricing (min-width: 44rem) {
    .mk-pricing-title { font-size: 2.25rem; }
    .mk-plans { grid-template-columns: repeat(3, minmax(0, 1fr)); align-items: center; }
    /* the featured plan stands a little taller than its neighbours */
    .mk-plans > .mk-plan[data-featured],
    .mk-plans > .aura > .mk-plan { padding-block: 2.25rem; }
  }

  /* compare: a Table of features per plan - the featured column tinted */
  .mk-pricing-compare {
    width: 100%;
    overflow-x: auto;
    border: 1px solid var(--border);
    border-radius: var(--radius-xl);

    & .table { min-width: 36rem; }
    & :is(th, td):not(:first-child) { text-align: center; }
    & [data-featured] { background: color-mix(in oklch, var(--primary) 6%, transparent); }
    & thead [data-featured] { box-shadow: inset 0 3px 0 var(--primary); }
    & .mk-pricing-yes { color: var(--primary); }
    & .mk-pricing-no { color: var(--muted-foreground); opacity: 0.5; }
    & svg { width: 1rem; height: 1rem; vertical-align: middle; }
    & tbody th { font-weight: 500; text-align: start; }
  }

  /* compact: plans as rows of one list - name, price, CTA */
  .mk-plans[data-variant="compact"] {
    grid-template-columns: minmax(0, 1fr) !important;
    gap: 0;
    overflow: hidden;
    border: 1px solid var(--border);
    border-radius: var(--radius-xl);

    & .mk-plan {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(min(100%, 12rem), 1fr));
      align-items: center;
      gap: 0.75rem 1.5rem;
      padding: 1.25rem 1.5rem;
      border: 0;
      border-block-end: 1px solid var(--border);
      border-radius: 0;
      box-shadow: none;

      &:last-child { border-block-end: 0; }
      &[data-featured] { border: 0; border-block-end: 1px solid var(--border); background: color-mix(in oklch, var(--primary) 5%, var(--card)); }
      & :is(.mk-plan-body, .mk-plan-price, .mk-plan-cta) { padding: 0; margin: 0; }
      & .mk-plan-amount { font-size: 2rem; }
    }
  }

  /* wide: one plan, features in two columns beside the price */
  .mk-plan[data-variant="wide"] {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 18rem), 1fr));
    gap: 1.5rem 2.5rem;
    padding: 2rem;

    & > * { padding-inline: 0; }
    & .mk-plan-features { margin: 0; padding: 0; border: 0; columns: 2 12rem; display: block; }
    & .mk-plan-feature { margin-block-end: 0.75rem; break-inside: avoid; }
  }

  /* usage: a Slider picks the seats, an <output> shows the price */
  .mk-pricing-usage {
    display: grid;
    gap: 1rem;
    max-width: 36rem;
    margin-inline: auto;
    padding: 1.75rem;
    border: 1px solid var(--border);
    border-radius: var(--radius-xl);
    background: var(--card);

    & .mk-pricing-usage-row { display: flex; align-items: baseline; justify-content: space-between; gap: 1rem; }
    & output { font-size: 2.5rem; font-weight: 600; letter-spacing: -0.03em; font-variant-numeric: tabular-nums; }
  }

  /* cta: an enterprise strip - talk to sales */
  .mk-pricing-cta {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 1rem 2rem;
    padding: 1.5rem 1.75rem;
    border-radius: var(--radius-xl);
    background: var(--foreground);
    color: var(--background);

    & p { margin: 0.25rem 0 0; color: color-mix(in oklch, var(--background) 70%, transparent); font-size: 0.9375rem; }
    & strong { font-size: 1.125rem; }
  }

  /* -- Accessibility ------------------------------------------- */

  @media (forced-colors: active) {
    .mk-plan { border-color: CanvasText; }
    .mk-pricing-billing label:has(input:checked) { outline: 1px solid Highlight; }
  }
}

/* ── components/process-step/process-step.css ── */
/* -- Process Step (website · Company) -------------------------------------
   Explains one numbered stage of a workflow - steps joined by a line, vertical or across, with the current one highlighted. */

@layer components {
  /* every box in the block measures border-box - the same on any page */
  :where(.mk-process-step, .mk-process-step *, .mk-process-step ::before, .mk-process-step ::after) { box-sizing: border-box; }

  .mk-process-steps {
    container: mk-process-steps / inline-size;
    display: flex;
    flex-direction: column;
    width: 100%;
    margin: 0;
    padding: 0;
    list-style: none;
  }
  .mk-process-step {
    position: relative;
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    align-content: start;
    gap: 1.25rem;
    padding-block-end: 2rem;

    /* the line to the next step */
    &:not(:last-child)::before {
      content: "";
      position: absolute;
      inset-inline-start: 1.25rem;
      top: 2.75rem;
      bottom: 0.25rem;
      width: 2px;
      translate: -50% 0;
      background: var(--border);
    }
    &:last-child { padding-block-end: 0; }
  }
  .mk-process-step-number {
    display: grid;
    place-items: center;
    width: 2.5rem;
    height: 2.5rem;
    border: 2px solid var(--border);
    border-radius: 50%;
    background: var(--background);
    font-family: var(--font-mono);
    font-size: 0.8125rem;
    font-weight: 600;
  }
  .mk-process-step[aria-current] .mk-process-step-number { border-color: var(--primary); background: var(--primary); color: var(--primary-foreground); }
  .mk-process-step-body { display: grid; gap: 0.25rem; padding-block-start: 0.375rem; }
  .mk-process-step-title { margin: 0; font-size: 1.0625rem; font-weight: 600; }
  .mk-process-step-desc { margin: 0; color: var(--muted-foreground); font-size: 0.9375rem; line-height: 1.6; text-wrap: pretty; }

  /* horizontal: a wrapping row - the list is the container, so only its
     steps change with its width (a container cannot query itself) */
  .mk-process-steps[data-variant="horizontal"] { flex-direction: row; flex-wrap: wrap; }
  .mk-process-steps[data-variant="horizontal"] > .mk-process-step { flex: 1 1 100%; }

  @container mk-process-steps (min-width: 40rem) {
    .mk-process-steps[data-variant="horizontal"] > .mk-process-step {
      flex: 1 1 0;
      grid-template-columns: minmax(0, 1fr);
      gap: 1rem;
      padding: 0 1.5rem 0 0;

      &:not(:last-child)::before { inset-inline-start: 3.25rem; inset-inline-end: 0.5rem; top: 1.25rem; bottom: auto; width: auto; height: 2px; translate: 0 -50%; }
    }
  }

  /* -- Accessibility ------------------------------------------- */
  @media (forced-colors: active) {
    .mk-process-step:not(:last-child)::before { background: CanvasText; }
    .mk-process-step[aria-current] .mk-process-step-number { border-color: Highlight; background: Highlight; color: HighlightText; }
  }
}

/* ── components/product-item/product-item.css ── */
/* -- Product Item (website · Shop) ----------------------------------------
   Displays one catalog entry with its image, name, price, and link - a second picture on hover, badges, rating, colors, a wishlist heart and add to cart. */

@layer components {
  /* every box in the block measures border-box - the same on any page */
  :where(.mk-product-item, .mk-product-item *, .mk-product-item ::before, .mk-product-item ::after) { box-sizing: border-box; }

  .mk-product-item { display: grid; gap: 0.875rem; align-content: start; }
  .mk-product-item { position: relative; }
  .mk-product-item-name a::after { content: ""; position: absolute; inset: 0; border-radius: inherit; }
  .mk-product-item-name a:focus-visible { outline: none; }
  .mk-product-item:has(.mk-product-item-name a:focus-visible) { outline: 2px solid var(--ring); outline-offset: 2px; }
  /* zero specificity: any block rule may still position its controls */
  :where(.mk-product-item :is(button, input, select, label, .btn):not(.mk-product-item-name a)) { position: relative; z-index: 1; }
  .mk-product-item-media { position: relative; overflow: hidden; border-radius: var(--radius-xl); background: var(--muted); }
  .mk-product-item-image { display: block; width: 100%; aspect-ratio: 4 / 5; object-fit: cover; transition: opacity 400ms ease;
    &[data-hover] { position: absolute; inset: 0; height: 100%; opacity: 0; }
  }
  .mk-product-item:hover .mk-product-item-image[data-hover] { opacity: 1; }
  /* on a photo, a badge needs a solid fill */
  .mk-product-item-badge { position: absolute; top: 0.75rem; left: 0.75rem; z-index: 1; box-shadow: var(--shadow-sm);
    &[data-sale] { background: var(--destructive); color: #fff; }
  }
  .mk-product-item-wish {
    position: absolute;
    top: 0.625rem;
    right: 0.625rem;
    z-index: 2;
    display: grid;
    place-items: center;
    width: 2.25rem;
    height: 2.25rem;
    border-radius: 999px;
    background: color-mix(in oklch, var(--background) 85%, transparent);
    color: var(--foreground);
    box-shadow: var(--shadow-sm);
    cursor: pointer;
    backdrop-filter: blur(6px);

    & input { position: absolute; inset: 0; margin: 0; opacity: 0; cursor: pointer; }
    & svg { width: 1.125rem; height: 1.125rem; transition: scale 200ms ease; }
    &:has(input:checked) { color: oklch(0.6 0.22 20); }
    &:has(input:checked) svg { fill: currentColor; scale: 1.1; }
    &:has(input:focus-visible) { outline: 2px solid var(--ring); outline-offset: 2px; }
  }
  .mk-product-item-body { display: grid; gap: 0.25rem; }
  .mk-product-item-name { margin: 0; font-size: 1rem; font-weight: 600;
    & a { color: inherit; text-decoration: none; }
  }
  .mk-product-item-desc { margin: 0; color: var(--muted-foreground); font-size: 0.875rem; }
  .mk-product-item-rating { display: flex; align-items: center; gap: 0.375rem; margin: 0; color: var(--muted-foreground); font-size: 0.8125rem; }
  .mk-product-item-stars {
    --mk-rating: 5;

    /* five ★ glyphs, filled to the rating by a clipped gradient */
    background: linear-gradient(90deg, oklch(0.78 0.16 75) calc(var(--mk-rating) / 5 * 100%), var(--border) 0);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    font-size: 0.9375rem;
    letter-spacing: 0.0625rem;
    line-height: 1;
  }
  .mk-product-item-price { display: flex; align-items: baseline; gap: 0.5rem; margin: 0.25rem 0 0; font-variant-numeric: tabular-nums;
    & strong { font-size: 1.0625rem; font-weight: 700; }
    & del { color: var(--muted-foreground); font-size: 0.875rem; }
    &:has(del) strong { color: var(--destructive); }
  }
  .mk-product-item-swatches { display: flex; gap: 0.375rem; margin: 0.375rem 0 0; padding: 0; list-style: none;
    & li { --mk-swatch: var(--muted); width: 1rem; height: 1rem; border-radius: 50%; background: var(--mk-swatch); box-shadow: inset 0 0 0 1px oklch(0 0 0 / 0.15); }
    & li[aria-current] { outline: 2px solid var(--foreground); outline-offset: 2px; }
  }
  .mk-product-item-add { justify-self: start; }

  .mk-product-item[data-variant="horizontal"] {
    grid-template-columns: minmax(7rem, 30%) minmax(0, 1fr);
    gap: 0.5rem 1.25rem;
    align-items: start;

    & .mk-product-item-media { grid-row: span 2; }
    & .mk-product-item-add { grid-column: 2; }
  }

  .mk-product-item[data-variant="minimal"] {
    text-align: center;

    & .mk-product-item-price { justify-content: center; }
    & :is(.mk-product-item-add, .mk-product-item-rating, .mk-product-item-swatches) { display: none; }
  }

  /* -- Accessibility ------------------------------------------- */
  @media (prefers-reduced-motion: reduce) {
    .mk-product-item-image, .mk-product-item-wish svg { transition: none; }
  }

  @media (forced-colors: active) {
    .mk-product-item-stars { background: none; }
    .mk-product-item-stars { color: CanvasText; }
    .mk-product-item-wish { border: 1px solid ButtonText; }
  }
}

/* ── components/product-showcase/product-showcase.css ── */
/* -- Product Showcase (marketing) ----------------------------------
   5:3 poster frame with a circular play button. One click (JS) sets
   data-state="playing": the poster and button hide, the native <video>
   appears with the browser's own controls. Layers stack; state flips
   visibility via CSS so the JS only ever changes an attribute. */

@layer components {
  .mk-showcase {
    container: mk-showcase / inline-size;
    position: relative;
    aspect-ratio: 5 / 3;
    width: 100%;
    max-width: 80rem;
    margin-inline: auto;
    overflow: hidden;
    border-radius: var(--radius-lg);
    background: var(--muted);

    /* poster, video (or an embed's <iframe> - YouTube, Vimeo) and play
       button share the same cover layer */
    & .mk-showcase-poster,
    & :is(video, iframe),
    & .mk-showcase-play {
      position: absolute;
      inset: 0;
    }

    & .mk-showcase-poster,
    & :is(video, iframe) {
      width: 100%;
      height: 100%;
      object-fit: cover;
      display: block;
      background: var(--muted);
    }

    & iframe { border: 0; }

    /* state layering: poster+button until 'playing', video after; a waiting
       embed takes no clicks - only the play button acts */
    & :is(video, iframe) { opacity: 0; }
    & iframe { pointer-events: none; }
    &[data-state='playing'] {
      & .mk-showcase-poster { opacity: 0; }
      & .mk-showcase-play { opacity: 0; visibility: hidden; }
      & :is(video, iframe) { opacity: 1; pointer-events: auto; }
    }
  }

  /* centered circular play button - real <button>, keyboard-focusable;
     inset auto + margin auto centers the 64px box in the full-inset cell */
  .mk-showcase-play {
    z-index: 10;
    inset: auto;
    margin: auto;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 4rem;
    height: 4rem;
    padding: 0.75rem;
    border: none;
    border-radius: 9999px;
    background: var(--background);
    box-shadow: var(--shadow-2xs);
    cursor: pointer;
    transition: opacity 200ms ease, scale 300ms ease;

    /* CSS wins over the `fill="none"` presentation attribute, so a lucide
       stroke icon renders as a solid glyph inside the circle */
    & svg { width: 1.5rem; height: 1.5rem; fill: currentColor; }
    &:hover { scale: 1.08; }
    &:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; }
  }


  /* -- variants ------------------------------------------------- */
  /* browser: a window bar with three dots on top; the layers sit below it */
  .mk-showcase[data-variant="browser"] {
    border: 1px solid var(--border);
    background: var(--card);
    box-shadow: var(--shadow-xl);

    &::before {
      content: "";
      position: absolute;
      inset: 0 0 auto;
      z-index: 11;
      height: 2.25rem;
      border-block-end: 1px solid var(--border);
      background:
        radial-gradient(circle at 1rem 50%, oklch(0.7 0.18 25) 0.3125rem, transparent 0.34rem),
        radial-gradient(circle at 1.75rem 50%, oklch(0.8 0.15 85) 0.3125rem, transparent 0.34rem),
        radial-gradient(circle at 2.5rem 50%, oklch(0.75 0.16 150) 0.3125rem, transparent 0.34rem),
        var(--muted);
    }
    & :is(.mk-showcase-poster, video, iframe) { inset: 2.25rem 0 0; height: calc(100% - 2.25rem); }
    & .mk-showcase-play { inset: 2.25rem 0 0; }
  }

  /* ratios: 16:9 for video, 1:1 for social / mobile */
  .mk-showcase[data-ratio="wide"] { aspect-ratio: 16 / 9; }
  .mk-showcase[data-ratio="square"] { aspect-ratio: 1; }

  /* a stage around the showcase: room for callouts, perspective for the tilt */
  .mk-showcase-stage {
    position: relative;
    width: 100%;
    max-width: 80rem;
    margin-inline: auto;
    padding: 1.5rem;
    perspective: 1400px;
  }

  /* callouts: small cards floating over the frame's corners */
  .mk-showcase-callout {
    position: absolute;
    z-index: 12;
    display: flex;
    align-items: center;
    gap: 0.625rem;
    max-width: 16rem;
    padding: 0.625rem 0.875rem;
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
